#' Empirical level or power of the goodness-of-fit test
#'
#' @description
#' Repeats [gof_test()] on `n_rep` independent data sets generated by a
#' function, and returns the rejection rate of each of the four statistics.
#' When the data are generated under the candidate model, this rate is the
#' empirical level of the test, to be compared with `alpha`; otherwise it is
#' the empirical power against the generating model.
#'
#' @param generate Function without argument that returns one data set, in
#'   any form accepted by [gof_data()], for instance
#'   `function() sim_model(0:50, "gamma", c(a = 2, b = 3), n_traj = 6)`.
#' @param model Candidate model under the null hypothesis, as in
#'   [gof_test()].
#' @param n_rep Number of data sets (default 100).
#' @param B Number of bootstrap samples of each test (default 200).
#' @param n_pool Size of the simulated pools; by default \eqn{100 m}.
#' @param alpha Significance level of the test (default 0.05).
#' @param failure What to do with a data set to which the candidate model
#'   cannot be fitted, for instance increasing models with negative
#'   increments: `"reject"` (default) counts it as a rejection by the four
#'   statistics, since such data are not consistent with the model;
#'   `"exclude"` removes it from the rates.
#' @param progress `TRUE` to display a progress bar.
#'
#' @details
#' The empirical level and power are Monte Carlo estimates: their standard
#' error, \eqn{\sqrt{p(1-p)/n}} for a rate \eqn{p} computed on \eqn{n} data
#' sets, is printed with the results. It is about 0.022 for a level of 0.05
#' with 100 data sets, and 0.007 with 1000 data sets.
#'
#' The computing time is about `n_rep` times that of one test. A study with
#' `n_rep = 1000` and `B = 1000`, as in the article, takes hours; start with
#' small values. The number of data sets to which the model could not be
#' fitted is always reported, so that a power due to these failures can be
#' told apart from a power due to the test.
#'
#' @return An object of class `gof_power`, a list with
#'   * `rate`: rejection rate of each statistic;
#'   * `se`: Monte Carlo standard error of each rate;
#'   * `rejections`: logical matrix of the decisions, one row per data set
#'     (rows of the excluded data sets removed);
#'   * `n_rep`, `n_failed`: number of data sets and number of data sets to
#'     which the model could not be fitted;
#'   * `model`, `alpha`, `B`, `failure`: settings of the study.
#'
#' @references
#' Zheng, J., Wang, Y., Chen, Y. and Xie, M. (2026). Automated verification
#' of degradation models using goodness-of-fit test based on similarity
#' measures and parametric bootstrap. *Quality and Reliability Engineering
#' International*. \doi{10.1002/qre.70382}
#'
#' @seealso [gof_test()], [sim_model()], [sim_path()]
#'
#' @examples
#' # Very small values to keep the examples fast: in practice use
#' # n_rep = 1000 and B = 1000, as in the article.
#' t <- 0:20
#'
#' # 1. Empirical level: data generated under the gamma model
#' set.seed(1)
#' power_study(function() sim_model(t, "gamma", c(a = 2, b = 3), n_traj = 6),
#'             model = "gamma", n_rep = 10, B = 30, n_pool = 150)
#'
#' # 2. Power of the Wiener model against concave Wiener paths
#' power_study(function() sim_model(t, "wiener_power", c(mu = 1, sigma = 0.3, r = 0.5), n_traj = 6),
#'             model = "wiener", n_rep = 10, B = 30, n_pool = 150)
#'
#' # 3. Power of the Wiener model against linear general paths
#' power_study(function() sim_path(t, "linear", phi_mean = 0.2, phi_sd = 0.05,
#'                                 sigma_eps = 0.05, n_traj = 6),
#'             model = "wiener", n_rep = 10, B = 30, n_pool = 150)
#'
#' # 4. Wiener data tested against the gamma model: negative increments make
#' #    the gamma model impossible; the failures are counted as rejections
#' #    by default, or excluded
#' gen <- function() sim_model(t, "wiener", c(mu = 0.5, sigma = 0.5), n_traj = 6)
#' power_study(gen, model = "gamma", n_rep = 10, B = 30, n_pool = 150)
#' @export
power_study <- function(generate, model, n_rep = 100, B = 200, n_pool = NULL, alpha = 0.05,
                        failure = c("reject", "exclude"), progress = FALSE) {
  if (!is.function(generate)) stop("generate must be a function without argument returning a data set")
  failure <- match.arg(failure)
  mod <- get_model(model)
  if (!is.numeric(n_rep) || length(n_rep) != 1 || n_rep < 1) stop("n_rep must be a positive integer")

  stat_names <- c("KS_sup", "KS_sum", "CvM_sup", "CvM_sum")
  rej <- matrix(NA, n_rep, 4, dimnames = list(NULL, stat_names))
  fitted <- logical(n_rep)
  bar <- if (progress) utils::txtProgressBar(max = n_rep, style = 3)
  for (k in seq_len(n_rep)) {
    res <- tryCatch(suppressWarnings(gof_test(generate(), mod, B = B, n_pool = n_pool, alpha = alpha)),
                    error = function(e) NULL)
    fitted[k] <- !is.null(res)
    if (fitted[k]) rej[k, ] <- res$reject else if (failure == "reject") rej[k, ] <- TRUE
    if (progress) utils::setTxtProgressBar(bar, k)
  }
  if (progress) close(bar)
  if (failure == "exclude") rej <- rej[fitted, , drop = FALSE]
  if (nrow(rej) == 0) stop("the model could not be fitted to any data set")
  rate <- colMeans(rej)
  structure(list(rate = rate, se = sqrt(rate * (1 - rate) / nrow(rej)), rejections = rej,
                 n_rep = n_rep, n_failed = sum(!fitted), model = mod$name, alpha = alpha,
                 B = B, failure = failure),
            class = "gof_power")
}

#' @export
print.gof_power <- function(x, digits = 3, ...) {
  cat("\nRejection rates of the goodness-of-fit test,", x$model, "model under H0\n")
  cat(x$n_rep, "data sets,", x$B, "bootstrap samples per test, alpha =", x$alpha, "\n")
  if (x$n_failed) {
    cat(x$n_failed, "data set(s) to which the model could not be fitted:",
        if (x$failure == "reject") "counted as rejections\n" else "excluded\n")
  }
  cat("\n")
  print(data.frame(rate = round(x$rate, digits), se = round(x$se, digits)))
  invisible(x)
}
